// applyEmphasis converts the first __bold__ and _italic_ pair in the
// document to their HTML tags. The original implementation only ever
// substituted one pair of each marker type (the first "__" opens, the
// next "__" closes, and likewise for "_"); this preserves that behavior.
// "__" is handled before "_" so that bold markers are not mistaken for
// a pair of italic markers.
func applyEmphasis(markdown string) string {
	markdown = replaceFirst(markdown, "__", "<strong>")
	markdown = replaceFirst(markdown, "__", "</strong>")
	markdown = replaceFirst(markdown, "_", "<em>")
	return replaceFirst(markdown, "_", "</em>")
}

// replaceFirst returns s with the first occurrence of old replaced by
// new, or s unchanged if old is not present.
func replaceFirst(s, old, new string) string {
	if i := strings.Index(s, old); i >= 0 {
		return s[:i] + new + s[i+len(old):]
	}
	return s
}

